// Generated by qa-tester © 2026 Nikita Morozov (ניקיטה מורוזוב / Никита Морозов). All rights reserved. ID: QAT-NM-2026-344086DC45B0
// #c9d61e (d7d5078e6b85ee996fc9d61e) — состояния попытки и отчёта после сброса, практики и закрытия брошенной попытки.
// По УЖЕ существующим QA-данным (новых сбросов и звонков нет, только чтение) → @prod-safe. Кейсы ATT-001…ATT-004.
//  - исключительный сброс: попытка reset, отчёт cancelled (в т.ч. если отчёт был готов — решение пользователя 14.10, F-39 треб.7);
//    QA-r100b-K3-1645 (сброс 21.10 с «אישור חריג»): отчёт business «הניסיון הקודם אופס… ולכן הדוח שלו בוטל», строка «נדרש ניסיון חדש»;
//  - практика: transcription_status = not_applicable;
//  - брошенная попытка QA-r100a-AB-1642: duration_seconds = записанные секунды (65), а не время до закрытия cron (~47 мин).
import * as path from 'path';
import { test, expect } from '@playwright/test';
import { openWithApi } from '../support/api';

const HASH = '#c9d61e · #d7d5078e6b85ee996fc9d61e';
const ADMIN = path.resolve(__dirname, '../../../auth/admin.json');
const BUSINESS = path.resolve(__dirname, '../../../auth/business.json');

const RESET_CANDIDATE = process.env.QA_RESET_CANDIDATE || 'QA-r100b-K3-1645';
const RESET_READY_CANDIDATE = process.env.QA_RESET_READY_CANDIDATE || 'QA-G4b-K1-1357';
const ABANDONED_CANDIDATE = process.env.QA_ABANDONED_CANDIDATE || 'QA-r100a-AB-1642';

type SupportRow = {
  candidate_id: string;
  candidate_name: string;
  attempt_id: string | null;
  attempt_type: 'official' | 'practice' | null;
  attempt_status: string | null;
  transcription_status: string | null;
  report_status: string | null;
};

const SINCE = '2026-09-01T00:00:00Z';

test.describe(`Попытка и отчёт после сброса, практики и брошенной попытки (${HASH})`, () => {
  test.describe('admin — admin_list_support_status', () => {
    test.use({ storageState: ADMIN });

    test(`сброшенная попытка никогда не ждёт обработки: report_status только null или cancelled; ${RESET_CANDIDATE} и ${RESET_READY_CANDIDATE} — reset/cancelled @desktop @prod-safe ${HASH}`, async ({ page }) => {
      const api = await openWithApi(page, '/admin/support');
      const res = await api.rpc('admin_list_support_status', { p_failure: null, p_business_id: null, p_since: SINCE });
      expect(res.status(), await res.text()).toBe(200);
      const rows = (await res.json()) as SupportRow[];

      const reset = rows.filter((r) => r.attempt_status === 'reset');
      expect(reset.length, 'нет сброшенных попыток в QA-данных').toBeGreaterThan(0);
      // Источник: AC «הדוח של הניסיון המאופס אינו ממתין לעיבוד» + F-39 треб.7 «האיפוס … מאפס את סטטוס הדוח».
      for (const r of reset) {
        expect([null, 'cancelled'], `${r.candidate_name} (${r.attempt_id?.slice(0, 8)}): report_status после сброса`).toContain(r.report_status);
      }

      for (const name of [RESET_CANDIDATE, RESET_READY_CANDIDATE]) {
        const own = rows.filter((r) => r.candidate_name === name && r.attempt_type === 'official');
        expect(own.length, `нет официальной попытки «${name}»`).toBeGreaterThan(0);
        // Отчёт был готов до исключительного сброса — после сброса он cancelled, а не ready (решение пользователя 14.10).
        expect(own.some((r) => r.attempt_status === 'reset' && r.report_status === 'cancelled'), `${name}: ${JSON.stringify(own.map((r) => [r.attempt_status, r.report_status]))}`).toBeTruthy();
        expect(own.some((r) => r.attempt_status === 'reset' && r.report_status === 'ready'), `${name}: сброшенная попытка с отчётом «מוכן»`).toBeFalsy();
      }
    });

    test(`практика не ждёт транскрипции: у всех попыток practice transcription_status = not_applicable @desktop @prod-safe ${HASH}`, async ({ page }) => {
      const api = await openWithApi(page, '/admin/support');
      const res = await api.rpc('admin_list_support_status', { p_failure: null, p_business_id: null, p_since: SINCE });
      expect(res.status(), await res.text()).toBe(200);
      const practice = ((await res.json()) as SupportRow[]).filter((r) => r.attempt_type === 'practice');
      expect(practice.length, 'нет попыток-практик в QA-данных').toBeGreaterThan(0);
      // Источник: AC «ניסיון תרגול אינו ממתין לתמלול».
      for (const r of practice) {
        expect(r.transcription_status, `${r.candidate_name} (${r.attempt_id?.slice(0, 8)})`).toBe('not_applicable');
      }
    });
  });

  test.describe('business — список и отчёт', () => {
    test.use({ storageState: BUSINESS });

    test(`${RESET_CANDIDATE}: после исключительного сброса отчёт «הניסיון הקודם אופס… ולכן הדוח שלו בוטל», в списке «נדרש ניסיון חדש» @desktop @prod-safe ${HASH}`, async ({ page }) => {
      const api = await openWithApi(page, '/candidates');
      const list = (await (await api.rpc('list_candidates')).json()) as { id: string; full_name: string; attempt: unknown; invite: { status: string } | null }[];
      const c = list.filter((x) => x.full_name === RESET_CANDIDATE);
      expect(c, `кандидат «${RESET_CANDIDATE}»`).toHaveLength(1);
      expect(c[0].attempt, 'после сброса новой попытки нет (иначе кейс устарел — выбрать другого через QA_RESET_CANDIDATE)').toBeNull();

      // Источник: AC + F-39 треб.7 — отчёт сброшенной попытки отменён, нужна новая попытка.
      await page.goto(`/candidates/${c[0].id}/report`);
      await expect(page.getByText(/הניסיון הקודם אופס.*ולכן הדוח שלו בוטל/)).toBeVisible({ timeout: 30_000 });
      await expect(page.getByTestId('report-summary')).toHaveCount(0);

      // Статус приглашения после сброса: «נדרש ניסיון חדש» (после 23.10.2026 ссылка истекает → «פג תוקף»).
      const LABELS: Record<string, string> = { new_attempt_required: 'נדרש ניסיון חדש', expired: 'פג תוקף' };
      expect(Object.keys(LABELS), 'статус приглашения после сброса').toContain(c[0].invite?.status);
      await page.goto(`/candidates?q=${encodeURIComponent(RESET_CANDIDATE)}`);
      const row = page.getByTestId('candidate-row').filter({ has: page.locator('td[data-label="שם"]').getByText(RESET_CANDIDATE, { exact: true }) });
      await expect(row).toHaveCount(1);
      await expect(row.locator('td[data-label="ביצוע"]')).toContainText(LABELS[c[0].invite!.status]);
    });

    test(`${ABANDONED_CANDIDATE}: длительность брошенной попытки = записанные секунды (65), не время до закрытия (~47 мин) @desktop @prod-safe ${HASH}`, async ({ page }) => {
      const api = await openWithApi(page, '/candidates');
      const list = (await (await api.rpc('list_candidates')).json()) as {
        full_name: string;
        attempt: { status: string; created_at: string; ended_at: string; duration_seconds: number } | null;
      }[];
      const c = list.filter((x) => x.full_name === ABANDONED_CANDIDATE);
      expect(c, `кандидат «${ABANDONED_CANDIDATE}»`).toHaveLength(1);
      const a = c[0].attempt!;
      expect(a, 'нет попытки').toBeTruthy();
      expect(a.status).toBe('technical_failure');
      const wallClock = (Date.parse(a.ended_at) - Date.parse(a.created_at)) / 1000;
      // Источник: AC «משך ניסיון נטוש אינו כולל את זמן ההמתנה עד הסגירה» — разговор ≈ 77 с, запись 70.5 с, закрыт cron через ~47 мин.
      expect(wallClock, 'попытка закрыта не сразу (иначе кейс ничего не проверяет)').toBeGreaterThan(600);
      expect(a.duration_seconds, `duration_seconds при ${Math.round(wallClock)} с до закрытия`).toBeGreaterThan(0);
      expect(a.duration_seconds).toBeLessThanOrEqual(120);
    });
  });
});
